<?php require dirname(__DIR__).'/inc/page_helpers.php';moderator_required();if(page_post()){check_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(in_array($status,['resolved','dismissed'],true)){$db->prepare('UPDATE moderation_reports SET status=?,reviewed_by=?,reviewed_at=NOW() WHERE id=? AND status=\'pending\'')->execute([$status,$currentUser['id'],$id]);notice('Report updated.');}go('/Admin/Reports.php');}$reports=$db->query("SELECT r.*,u.username reporter FROM moderation_reports r JOIN users u ON u.id=r.reporter_id ORDER BY (r.status='pending') DESC,r.id DESC LIMIT 200")->fetchAll();page_start('Moderation Reports');?><section class="Panel"><h1>Moderation Reports</h1><?php foreach($reports as $r):?><article class="tile"><b>#<?=(int)$r['id']?> · <?=e($r['target_type'])?> #<?=(int)$r['target_id']?></b><p><?=nl2br(e($r['reason']))?></p><small>Reported by <?=e($r['reporter'])?> · <?=e($r['created_at'])?> · <?=e($r['status'])?></small><?php if($r['status']==='pending'):?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button name="status" value="resolved">Resolve</button> <button name="status" value="dismissed">Dismiss</button></form><?php endif;?></article><?php endforeach;?><?php if(!$reports):?><p>No reports.</p><?php endif;?></section><?php page_end();?>